Enabled\" />\n                </template>\n              </carousel>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script>\nimport { bus } from \"../../../app\";\n  import { Carousel, Slide, Navigation, Pagination } from 'vue3-carousel'\n  import 'vue3-carousel/dist/carousel.css'\n\n  export default {\n      components: { Carousel, Slide, Navigation, Pagination }, \n      props:['url','event_id'],\n      data(){\n        return {\n          pdate:'',\n          images: [],\n          photos: [],\n          overlay : false,   \n          navigationEnabled:true,\n          showImage:0,\n          dates:[\n  {\n    //path: this.url+'/uploads/events/event_1.jpg',\n    default: 1,\n    highlight: 1,\n  }\n],\n          success:null,\n          errors:[],\n          segment:'admin',\n          imageLink1: this.url+'/uploads/static/arrow-l.png',\n          imageLink2: this.url+'/uploads/static/arrow-r.png',\n          //imageLink3: this.url+'/uploads/static/bg.jpg',\n        }\n    },\n\n    created() {\n      //alert('asdas');\n\n      this.getSliderImage();\n      window.addEventListener('resize', this.handleResize)\n      this.handleResize();\n     \n      this.closeModal();\n\n        bus.$on(\"photoadded\",data => {\n        this.getSliderImage();\n        //Object.keys(this.photos).length=data;\n  \n    });\n\n    },\n\n    unmounted() {\n      window.removeEventListener('resize', this.handleResize)\n    },\n    \n    methods:{\n    \n     getSliderImage()  {\n//alert('dds');\n        axios.get(this.url+'/admin/display/photos/'+this.event_id).then(response => {\n         this.photos = response.data.data;\n         bus.$emit(\"imageCount\",Object.keys(this.photos).length);\n\n       \n         //console.log(this.photos);\n        }); \n        /*\n        this.photos=[{\"id\":1,\"photo\":\"\\/uploads\\/events\\/event_1.jpg\"},{\"id\":2,\"photo\":\"\\/uploads\\/events\\/event_2.jpg\"},{\"id\":3,\"photo\":\"\\